solution.solution.js:
class Money {
  constructor(cents, currency = "USD") {
    if (!Number.isInteger(cents)) throw new TypeError(`cents must be a whole number, got ${cents}`);
    this.cents = cents;
    this.currency = currency;
    Object.freeze(this);
  }

  add(other) {
    if (other.currency !== this.currency) {
      throw new Error(`cannot add ${other.currency} to ${this.currency}`);
    }
    return new Money(this.cents + other.cents, this.currency);
  }

  [Symbol.toPrimitive](hint) {
    if (hint === "number") return this.cents / 100;
    return `${(this.cents / 100).toFixed(2)} ${this.currency}`;
  }

  get [Symbol.toStringTag]() {
    return "Money";
  }

  static sum(list) {
    if (list.length === 0) return new Money(0);
    return list.reduce((total, m) => total.add(m), new Money(0, list[0].currency));
  }
}

unitTests:
test("adding and converting", () => {
  const a = new Money(1250);
  const b = new Money(275);
  const c = a.add(b);
  checkEq(`${c}`, "15.25 USD");
  checkEq(+c, 15.25);
  checkEq(String(new Money(5, "EUR")), "0.05 EUR");
  checkEq(Object.prototype.toString.call(a), "[object Money]");
  checkEq(a.cents, 1250);
});

test("rules", () => {
  checkThrows(() => new Money(12.5), TypeError);
  let message = "";
  try { new Money(1).add(new Money(1, "EUR")); } catch (e) { message = e.message; }
  check(message.includes("USD") && message.includes("EUR"), "the message should name both currencies");
  const m = new Money(100);
  check(Object.isFrozen(m), "Money objects should be frozen");
  checkEq(m.cents, 100);
});

test("sum", () => {
  checkEq(`${Money.sum([new Money(100, "GBP"), new Money(250, "GBP")])}`, "3.50 GBP");
  checkEq(`${Money.sum([])}`, "0.00 USD");
});

